//! MV3-G13b：单频道 hydration 的唯一终态、持久屏障和 RuntimeAuth 隔离。

use bytes::Bytes;
use helix_core::effect::{Effect, SqlValue, StorageOp};
use helix_core::tick::{AppCommand, PortError, PortOutcome, ReplyBytes};
use helix_core::{Correlation, EffectSink, Module, Tick};
use helix_im::{ImConfig, ImModule};
use serde_json::{json, Value};

const VIEWER: &str = "viewer-g13b";
const COMPANY: &str = "company-g13b";
const CHANNEL: &str = "chfixx0000000000000000003b";

// ADR-007 fixture body for the no-sync happy path; the HTTP request itself must still be generated by Helix.
const INCREMENT_BODY_B64: &str = "eyJkYXRhIjp7ImlkIjoiY2hmaXh4MDAwMDAwMDAwMDAwMDAwMDAwM2IiLCJ0ZWFtSWQiOiJjb21wYW55LWcxM2IiLCJkaXNwbGF5TmFtZSI6IkcxM2IiLCJsYXN0RXZlbnRTZXEiOjAsInVucmVhZENvdW50IjozLCJuZWVkU3luYyI6ZmFsc2UsIm1lbWJlckNvdW50IjoxLCJtZW1iZXJzIjpbeyJ1c2VySWQiOiJ2aWV3ZXItZzEzYiIsInJvbGUiOiJNRU1CRVIifV19fQ==";
const INCREMENT_NEEDS_SYNC_BODY_B64: &str = "eyJkYXRhIjp7ImlkIjoiY2hmaXh4MDAwMDAwMDAwMDAwMDAwMDAwM2IiLCJ0ZWFtSWQiOiJjb21wYW55LWcxM2IiLCJkaXNwbGF5TmFtZSI6IkcxM2IiLCJsYXN0RXZlbnRTZXEiOjIsIm5lZWRTeW5jIjp0cnVlLCJtZW1iZXJzIjpbeyJ1c2VySWQiOiJ2aWV3ZXItZzEzYiIsInJvbGUiOiJNRU1CRVIifV0sIm1lbWJlckNvdW50IjoxfX0=";
const NULL_BODY_B64: &str = "eyJkYXRhIjpudWxsfQ==";
const SYNC_NO_CHANGE_BODY_B64: &str = "eyJzdGF0dXMiOiJTVUNDRVNTIiwiZGF0YSI6eyJlbnRyaWVzIjpbeyJjaGFubmVsSWQiOiJjaGZpeHgwMDAwMDAwMDAwMDAwMDAwMDAzYiIsImtpbmQiOiJub19jaGFuZ2UiLCJldmVudHMiOltdLCJuZXh0U2VxIjoyfV19fQ==";
const SYNC_EVENTS_BODY_B64: &str = "";

/// 驱动真实 `ImModule::handle`，不旁路 outbound 或 PortReply owner。
struct Replay {
    module: ImModule,
    sink: EffectSink,
}

impl Replay {
    /// 创建带固定 RuntimeAuth 的单频道 hydration 回放器。
    fn new() -> Self {
        Self {
            module: ImModule::new(ImConfig {
                auth_user_id: VIEWER.to_string(),
                company_id: COMPANY.to_string(),
                api_base_url: "http://g13b.invalid/api/cses".to_string(),
                default_api_base_url: "http://g13b.invalid/api/cses".to_string(),
                ..ImConfig::default()
            }),
            sink: EffectSink::new(),
        }
    }

    /// 执行一步并清除上一步的 Effect batch。
    fn step(&mut self, tick: Tick) -> Result<(), String> {
        self.sink.clear();
        self.module
            .handle(&tick, 1_700_001_800_000, &mut self.sink)
            .map_err(|error| error.to_string())
    }

    /// 发起单频道 increment 命令并返回唯一 HTTP correlation。
    fn start(&mut self, channel_id: &str) -> Result<Correlation, String> {
        self.step(Tick::Command(AppCommand::new(
            "im_channel_load_increment_by_channel_id",
            serde_json::to_vec(&json!({ "channel_id": channel_id }))
                .map_err(|error| error.to_string())?,
        )))?;
        let http = self
            .sink
            .as_slice()
            .iter()
            .find_map(|effect| match effect {
                Effect::Http { corr, .. } => Some(*corr),
                _ => None,
            })
            .ok_or_else(|| "hydration command must emit one HTTP effect".to_string())?;
        let Effect::Http { req, .. } = self
            .sink
            .as_slice()
            .iter()
            .find(|effect| matches!(effect, Effect::Http { .. }))
            .expect("HTTP effect exists")
        else {
            unreachable!();
        };
        assert_eq!(req.method, "POST");
        assert!(req.url.ends_with("/channel/load/incrementByChannelId"));
        let body: Value = serde_json::from_slice(req.body.as_ref().expect("body"))
            .map_err(|error| error.to_string())?;
        assert_eq!(body, json!({ "channelId": channel_id }));
        Ok(http)
    }

    /// 回灌 ADR-007 HTTP 成功信封。
    fn reply_http(&mut self, corr: Correlation, body_b64: &str) -> Result<(), String> {
        self.step(Tick::PortReply {
            corr,
            outcome: PortOutcome::Ok(ReplyBytes(Bytes::from(
                serde_json::to_vec(&json!({
                    "status": 200,
                    "headers": [],
                    "body": body_b64,
                }))
                .map_err(|error| error.to_string())?,
            ))),
        })
    }

    /// 返回当前 batch 中的 sync/notify HTTP correlation。
    fn sync_corr(&self) -> Option<Correlation> {
        self.sink.as_slice().iter().find_map(|effect| match effect {
            Effect::Http { corr, req } if req.url.ends_with("/channel/sync/notify") => Some(*corr),
            _ => None,
        })
    }

    /// 返回当前 batch 中的持久化 correlation（普通或原子写）。
    fn write_corr(&self) -> Option<Correlation> {
        self.sink.as_slice().iter().find_map(|effect| match effect {
            Effect::Persist { corr, .. } | Effect::PersistAtomic { corr, .. } => Some(*corr),
            _ => None,
        })
    }

    /// 回灌一个持久化成功回执并返回新产生的 effects。
    fn reply_persist_ok(&mut self, corr: Correlation) -> Result<(), String> {
        self.step(Tick::PortReply {
            corr,
            outcome: PortOutcome::Ok(ReplyBytes(Bytes::new())),
        })
    }

    /// 回灌一个本地 Scan/Get rows 回执。
    fn reply_rows(&mut self, corr: Correlation, rows: Value) -> Result<(), String> {
        self.step(Tick::PortReply {
            corr,
            outcome: PortOutcome::Ok(ReplyBytes(Bytes::from(
                serde_json::to_vec(&rows).map_err(|error| error.to_string())?,
            ))),
        })
    }

    /// 回灌一个端口失败回执。
    fn reply_err(&mut self, corr: Correlation) -> Result<(), String> {
        self.step(Tick::PortReply {
            corr,
            outcome: PortOutcome::Err(PortError::Http(502)),
        })
    }

    /// 提取当前 Effect batch 中的 Emit JSON。
    fn events(&self) -> Vec<Value> {
        self.sink
            .as_slice()
            .iter()
            .filter_map(|effect| match effect {
                Effect::Emit { event } => serde_json::from_slice(event.0.as_ref()).ok(),
                _ => None,
            })
            .collect()
    }

    /// 返回当前 batch 的 hydration 原子屏障 correlation。
    fn persist_corr(&self) -> Option<Correlation> {
        self.sink.as_slice().iter().find_map(|effect| match effect {
            Effect::PersistAtomic { corr, .. } => Some(*corr),
            _ => None,
        })
    }

    /// 顺序回放 channel/member/message/cursor 四段 durable read-back。
    fn complete_readback(&mut self) -> Result<(), String> {
        for _ in 0..4 {
            let (corr, table) = self
                .sink
                .as_slice()
                .iter()
                .find_map(|effect| match effect {
                    Effect::Persist { corr, ops } => ops.first().map(|op| {
                        let table = match op {
                            helix_core::effect::StorageOp::Get(spec) => spec.table,
                            helix_core::effect::StorageOp::ScopedGet(spec) => spec.table,
                            helix_core::effect::StorageOp::Scan(spec) => spec.table,
                            _ => "",
                        };
                        (*corr, table)
                    }),
                    _ => None,
                })
                .ok_or_else(|| {
                    format!(
                        "expected next hydration read-back Persist; effects={:?}; events={:?}",
                        self.sink.as_slice(),
                        self.events()
                    )
                })?;
            let rows = match table {
                "channel" => json!([{
                    "id": CHANNEL,
                    "display_name": "G13b",
                    "team_id": COMPANY,
                    "user_id": VIEWER,
                    "members": "[]",
                    "unread_count": 3,
                }]),
                "channel_member" => json!([{
                    "channel_id": CHANNEL,
                    "user_id": VIEWER,
                    "team_id": COMPANY,
                    "role": "MEMBER",
                    "unread_count": 3,
                }]),
                "message" => json!([]),
                "channel_event_cursor" => json!([{
                    "channel_id": CHANNEL,
                    "last_event_seq": 0,
                }]),
                other => return Err(format!("unexpected hydration read-back table {other}")),
            };
            self.reply_rows(corr, rows)?;
            if !self.events().is_empty() {
                return Ok(());
            }
        }
        Err("hydration read-back did not produce terminal result".to_string())
    }
}

/// HTTP 成功只接收 authority；未过 channel/member durable barrier 前不得提前发布 Result 或业务事件。
#[test]
fn hydration_http_waits_for_channel_member_persist_and_has_no_legacy_emit() -> Result<(), String> {
    let mut replay = Replay::new();
    let http_corr = replay.start(CHANNEL)?;
    replay.reply_http(http_corr, INCREMENT_BODY_B64)?;

    assert!(
        replay.events().is_empty(),
        "HTTP admission must not emit terminal result"
    );
    let persist_corr = replay
        .persist_corr()
        .ok_or_else(|| "increment must persist channel/member before terminal work".to_string())?;
    assert!(replay
        .sink
        .as_slice()
        .iter()
        .all(|effect| { !matches!(effect, Effect::Http { .. } | Effect::Send { .. }) }));

    replay.reply_persist_ok(persist_corr)?;
    assert!(
        replay.events().is_empty(),
        "hydration must not emit channel_hydrated or read result before read-back"
    );
    assert!(replay
        .sink
        .as_slice()
        .iter()
        .all(|effect| { !matches!(effect, Effect::Http { .. } | Effect::Send { .. }) }));
    Ok(())
}

/// increment authority 必须在首个原子屏障写入 viewer 未读绝对态与对应业务水位。
#[test]
fn hydration_increment_persists_viewer_unread_authority_before_history() -> Result<(), String> {
    let mut replay = Replay::new();
    let http_corr = replay.start(CHANNEL)?;
    replay.reply_http(http_corr, INCREMENT_BODY_B64)?;

    let rows = replay
        .sink
        .as_slice()
        .iter()
        .find_map(|effect| match effect {
            Effect::PersistAtomic { ops, .. } => ops.iter().find_map(|op| match op {
                StorageOp::BatchUpsert(spec) if spec.table == "channel_member" => Some(&spec.rows),
                _ => None,
            }),
            _ => None,
        })
        .ok_or_else(|| "hydration must persist channel_member authority".to_string())?;
    let viewer = rows
        .iter()
        .find(|row| {
            row.iter().any(|(name, value)| {
                name == "user_id" && matches!(value, SqlValue::Text(id) if id == VIEWER)
            })
        })
        .ok_or_else(|| "hydration member write must contain current viewer".to_string())?;
    assert!(viewer
        .iter()
        .any(|(name, value)| { name == "unread_count" && matches!(value, SqlValue::Integer(3)) }));
    assert!(viewer.iter().any(|(name, value)| {
        name == "last_unread_event_seq" && matches!(value, SqlValue::Integer(0))
    }));
    Ok(())
}

/// no-sync hydration 必须最终只释放一个 typed Result，不触发 dialog/messages 查询或业务广播。
#[test]
fn hydration_no_sync_releases_one_typed_result_only() -> Result<(), String> {
    let mut replay = Replay::new();
    let http_corr = replay.start(CHANNEL)?;
    replay.reply_http(http_corr, INCREMENT_BODY_B64)?;
    let persist_corr = replay.persist_corr().expect("persist correlation");
    replay.reply_persist_ok(persist_corr)?;
    replay.complete_readback()?;

    let events = replay.events();
    assert_eq!(
        events.len(),
        1,
        "one hydration request must have one terminal Result"
    );
    assert_eq!(events[0]["event"], "im:read:result");
    assert!(events[0]["data"]["req_id"].as_str().is_some());
    assert_eq!(events[0]["data"]["body"]["channelId"], CHANNEL);
    assert_eq!(
        events[0]["data"]["body"]["unreadReconcile"],
        json!({"authority": 3, "local": 3, "status": "match"})
    );
    assert!(replay
        .sink
        .as_slice()
        .iter()
        .all(|effect| { !matches!(effect, Effect::Http { .. } | Effect::Send { .. }) }));
    Ok(())
}

/// data=null 是合法未找到终态：只回一个 null Result，不能制造空 channel shell。
#[test]
fn hydration_missing_channel_is_one_null_result_without_storage_write() -> Result<(), String> {
    let mut replay = Replay::new();
    let http_corr = replay.start(CHANNEL)?;
    replay.reply_http(http_corr, NULL_BODY_B64)?;

    let events = replay.events();
    assert_eq!(events.len(), 1);
    assert_eq!(events[0]["event"], "im:read:result");
    assert!(events[0]["data"]["body"].is_null());
    assert!(replay
        .sink
        .as_slice()
        .iter()
        .all(|effect| !matches!(effect, Effect::Persist { .. })));
    Ok(())
}

/// HTTP 失败必须只释放一个 error Result，旧 channel/window/cursor 不应被清理或广播。
#[test]
fn hydration_http_failure_is_single_terminal_error() -> Result<(), String> {
    let mut replay = Replay::new();
    let http_corr = replay.start(CHANNEL)?;
    replay.reply_err(http_corr)?;
    let events = replay.events();
    assert_eq!(events.len(), 1);
    assert_eq!(events[0]["event"], "im:read:result");
    assert!(events[0]["data"]["error"].is_string());
    assert!(replay.sink.as_slice().iter().all(|effect| {
        !matches!(
            effect,
            Effect::Persist { .. } | Effect::Http { .. } | Effect::Send { .. }
        )
    }));
    Ok(())
}

/// channel/member durable 失败不能释放成功终态，也不能触发 sync 或读回。
#[test]
fn hydration_channel_member_failure_preserves_terminal_boundary() -> Result<(), String> {
    let mut replay = Replay::new();
    let http_corr = replay.start(CHANNEL)?;
    replay.reply_http(http_corr, INCREMENT_BODY_B64)?;
    let persist_corr = replay.persist_corr().expect("persist correlation");
    replay.reply_err(persist_corr)?;
    let events = replay.events();
    assert_eq!(events.len(), 1, "failed persist must settle once");
    assert!(events[0]["data"]["error"].is_string());
    assert!(replay
        .sink
        .as_slice()
        .iter()
        .all(|effect| { !matches!(effect, Effect::Http { .. } | Effect::Send { .. }) }));
    Ok(())
}

/// needSync 必须在 channel/member durable 成功后才发 sync，并从 durable cursor=0 起拉取。
#[test]
fn hydration_need_sync_waits_for_sync_then_readback() -> Result<(), String> {
    let mut replay = Replay::new();
    let http_corr = replay.start(CHANNEL)?;
    replay.reply_http(http_corr, INCREMENT_NEEDS_SYNC_BODY_B64)?;
    let persist_corr = replay
        .persist_corr()
        .expect("channel/member persist correlation");
    replay.reply_persist_ok(persist_corr)?;
    assert!(
        replay.events().is_empty(),
        "hydration increment barrier leaked events: {:?}",
        replay.events()
    );
    let sync_corr = replay
        .sync_corr()
        .ok_or_else(|| "needSync must issue sync/notify after durable increment".to_string())?;
    let Effect::Http { req, .. } = replay
        .sink
        .as_slice()
        .iter()
        .find(|effect| matches!(effect, Effect::Http { req, .. } if req.url.ends_with("/channel/sync/notify")))
        .expect("sync effect")
    else {
        unreachable!();
    };
    let body: Value = serde_json::from_slice(req.body.as_ref().expect("sync body"))
        .map_err(|error| error.to_string())?;
    assert_eq!(
        body,
        json!({
            "cursors": [{"channelId": CHANNEL, "fromSeq": 0}]
        })
    );
    replay.reply_http(sync_corr, SYNC_NO_CHANGE_BODY_B64)?;
    assert!(replay.events().is_empty());
    replay.complete_readback()?;
    let events = replay.events();
    assert_eq!(events.len(), 1);
    assert_eq!(events[0]["event"], "im:read:result");
    assert_eq!(events[0]["data"]["body"]["cursor"], 0);
    Ok(())
}

/// sync/notify 失败必须一次性结算 error，不能清理旧 channel/cursor 或发布 sync-state。
#[test]
fn hydration_sync_failure_is_single_terminal_error() -> Result<(), String> {
    let mut replay = Replay::new();
    let http_corr = replay.start(CHANNEL)?;
    replay.reply_http(http_corr, INCREMENT_NEEDS_SYNC_BODY_B64)?;
    let persist_corr = replay
        .persist_corr()
        .expect("channel/member persist correlation");
    replay.reply_persist_ok(persist_corr)?;
    let sync_corr = replay.sync_corr().expect("sync correlation");
    replay.reply_err(sync_corr)?;
    let events = replay.events();
    assert_eq!(events.len(), 1);
    assert!(events[0]["data"]["error"].is_string());
    assert!(replay.sink.as_slice().iter().all(|effect| {
        !matches!(
            effect,
            Effect::Persist { .. } | Effect::PersistAtomic { .. } | Effect::Http { .. }
        )
    }));
    Ok(())
}

/// 历史 events 走原子 window+cursor 写入并重建 viewer 未读；hydration 不提前释放业务事件。
#[test]
fn hydration_events_use_atomic_history_cursor_without_business_events() -> Result<(), String> {
    let mut replay = Replay::new();
    let http_corr = replay.start(CHANNEL)?;
    replay.reply_http(http_corr, INCREMENT_NEEDS_SYNC_BODY_B64)?;
    let increment_corr = replay
        .persist_corr()
        .expect("increment persist correlation");
    replay.reply_persist_ok(increment_corr)?;
    let sync_corr = replay.sync_corr().expect("sync correlation");
    replay.reply_http(sync_corr, SYNC_EVENTS_BODY_B64)?;
    assert!(replay.events().is_empty());
    let history_corr = replay
        .write_corr()
        .expect("history PersistAtomic correlation");
    let history_ops = replay
        .sink
        .as_slice()
        .iter()
        .find_map(|effect| match effect {
            Effect::PersistAtomic { corr, ops } if *corr == history_corr => Some(ops),
            _ => None,
        })
        .expect("history atomic ops");
    let debug = format!("{history_ops:?}");
    assert!(
        debug.contains("ScopedGuardedBump") && debug.contains("last_unread_event_seq"),
        "缺少 increment unread authority 时，history 必须以 per-viewer guard 重建未读"
    );
    replay.reply_persist_ok(history_corr)?;
    assert!(replay.events().is_empty());
    replay.complete_readback()?;
    let events = replay.events();
    assert_eq!(events.len(), 1);
    assert_eq!(events[0]["event"], "im:read:result");
    assert_eq!(
        events[0]["data"]["body"]["messages"]
            .as_array()
            .unwrap()
            .len(),
        0
    );
    Ok(())
}

/// 回报 corr 只能消费一次；迟到/重复 HTTP 回报不能产生第二个终态。
#[test]
fn hydration_terminal_is_idempotent_for_late_reply() -> Result<(), String> {
    let mut replay = Replay::new();
    let http_corr = replay.start(CHANNEL)?;
    replay.reply_err(http_corr)?;
    assert_eq!(replay.events().len(), 1);
    replay.reply_err(http_corr)?;
    assert!(replay.events().is_empty());
    Ok(())
}
